// Prisma 7 clients for the database lane, generated by scripts/test-db.sh from ./prisma/<dialect>/ into the git-ignored
// packages/cloudrop/.prisma-client/. They are imported by path at run time, so typechecking never needs a generated
// client; the structural type below mirrors the generated declarations the tests rely on.

import { existsSync } from "node:fs";
import { PrismaBetterSqlite3 } from "@prisma/adapter-better-sqlite3";
import { PrismaPg } from "@prisma/adapter-pg";
import type { PostgresTestDatabase } from "./postgres.ts";
import type { SqliteTestDatabase } from "./sqlite.ts";

type Row = Record<string, unknown>;

/** The model calls the tests make, loosely typed: the generated types would tie typechecking to the generate step. */
export interface PrismaTestModel {
  findUnique(args: { where: Row }): Promise<Row | null>;
  create(args: { data: Row }): Promise<Row>;
  update(args: { where: Row; data: Row }): Promise<Row>;
}

/** What an interactive transaction's callback receives: the client without `$transaction` and `$disconnect`. */
export interface PrismaTestTransaction {
  $queryRawUnsafe<T = unknown>(sql: string, ...values: unknown[]): Promise<T>;
  $executeRawUnsafe(sql: string, ...values: unknown[]): Promise<number>;
  cloudropFile: PrismaTestModel;
  cloudropUsage: PrismaTestModel;
}

export interface PrismaTestClient extends PrismaTestTransaction {
  // The two forms in the order the generated client declares them (.prisma-client/*/internal/class.ts, 7.10.1).
  $transaction<P extends Promise<unknown>[]>(
    queries: [...P],
    options?: { isolationLevel?: string },
  ): Promise<unknown[]>;
  $transaction<R>(
    run: (tx: PrismaTestTransaction) => Promise<R>,
    options?: { maxWait?: number; timeout?: number; isolationLevel?: string },
  ): Promise<R>;
  $disconnect(): Promise<void>;
}

/** The part of a better-sqlite3 `Database` a test needs: registering a function a trigger can call. */
export interface SqliteFunctionHost {
  function(name: string, options: { deterministic: boolean }, run: () => number): unknown;
}

export interface PrismaClientOptions {
  /** SQLite: called with Prisma's own better-sqlite3 connection whenever Prisma opens it. */
  onSqliteConnection?: (connection: SqliteFunctionHost) => void;
}

type PrismaClientClass = new (options: { adapter: PrismaPg | PrismaBetterSqlite3 }) => PrismaTestClient;

async function loadClient(dialect: "postgres" | "sqlite"): Promise<PrismaClientClass> {
  const file = new URL(`../../../.prisma-client/${dialect}/client.ts`, import.meta.url);
  if (!existsSync(file)) {
    throw new Error(
      `The Prisma test client for ${dialect} is not generated. Run the database tests with \`bun run test:db\`, which generates it.`,
    );
  }
  // The generated module's own types would tie typechecking to the generate step.
  const module = (await import(/* @vite-ignore */ file.href)) as { PrismaClient: PrismaClientClass };
  return module.PrismaClient;
}

/** The adapter factory, with `onConnection` given each connection it opens (the adapter keeps it as `client`). */
function sqliteAdapter(url: string, onConnection: PrismaClientOptions["onSqliteConnection"]): PrismaBetterSqlite3 {
  const factory = new PrismaBetterSqlite3({ url });
  if (!onConnection) return factory;
  const connect = factory.connect.bind(factory);
  factory.connect = async () => {
    const adapter = await connect();
    onConnection((adapter as unknown as { client: SqliteFunctionHost }).client);
    return adapter;
  };
  return factory;
}

/**
 * A Prisma client on the fixture's database: on Postgres in its schema, on SQLite
 * on its file (open the fixture with `{ file: true }`). The caller disconnects it, registering that as soon as it has
 * the client.
 */
export async function openPrismaClient(
  db: PostgresTestDatabase | SqliteTestDatabase,
  options: PrismaClientOptions = {},
): Promise<PrismaTestClient> {
  if (db.dialect === "postgres") {
    const PrismaClient = await loadClient("postgres");
    // The URL's search path reaches raw queries only: model queries name the schema, which PrismaPg takes as `schema`.
    return new PrismaClient({ adapter: new PrismaPg({ connectionString: db.url }, { schema: db.schema }) });
  }
  if (!db.path) throw new Error("Prisma opens SQLite by file: call useSqliteDatabase({ file: true }).");
  const PrismaClient = await loadClient("sqlite");
  return new PrismaClient({ adapter: sqliteAdapter(`file:${db.path}`, options.onSqliteConnection) });
}
